-- WP-12 tests first: real PostgreSQL roles, synthetic rolled-back fixtures.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
insert into auth.users(id,email) values
 ('12000000-0000-4000-8000-000000000001','wp12-sql-a@example.invalid'),
 ('12000000-0000-4000-8000-000000000002','wp12-sql-b@example.invalid');
create temporary table wp12(label text primary key,id uuid,version text);
grant select,insert,update on wp12 to authenticated;
select ok(to_regprocedure('public.save_draft_setup(uuid,text,text,text,text,boolean,text,jsonb)') is not null,'setup operation exists');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp12 values('a',public.create_wedding('WP12 synthetic A','Test city'),null);
select lives_ok($$select public.save_draft_setup((select id from wp12 where label='a'),(select state_version from public.weddings),'A draft','Pune',null,true,null,'[{"title":"Wedding/Pheras","ceremony_date":null,"guest_count":null},{"title":"Reception","ceremony_date":"2027-02-15","guest_count":250}]')$$,'two-ceremony setup persists');
select is((select count(*) from public.ceremonies),2::bigint,'only chosen ceremonies exist');
select is((select budget_ceiling_paise from public.weddings),null::text,'budget unknown remains NULL');
select is((select guest_count from public.ceremonies where title='Wedding/Pheras'),null::integer,'no invented guest ratio');
update wp12 set version=(select state_version from public.weddings) where label='a';
select is(public.generate_draft((select id from wp12 where label='a'),(select version from wp12 where label='a')),12,'six shared plus three per ceremony generated');
select is((select count(*) from public.tasks where due_date is not null),0::bigint,'no invented template dates even with a known ceremony date');
select is((select count(*) from public.tasks where template_key is not null),12::bigint,'stable template identities stored');
update wp12 set version=(select state_version from public.weddings) where label='a';
select is(public.generate_draft((select id from wp12 where label='a'),'0'),0,'repeat generation idempotent with original stale version');
select is((select state_version from public.weddings),(select version from wp12 where label='a'),'repeat generation does not bump version');
select is((select count(*) from public.tasks),12::bigint,'repeat generation has no duplicates');
select lives_ok($$select public.edit_draft_task((select id from wp12 where label='a'),(select id from public.tasks where template_key='shared.roles.v1'),(select state_version from public.weddings),'Edited synthetic task','Synthetic notes','Sample proxy','2027-01-10')$$,'draft task edit supported');
select is((select due_date::text from public.tasks where template_key='shared.roles.v1'),'2027-01-10','manual date-only input retained');
select lives_ok($$select public.add_draft_task((select id from wp12 where label='a'),(select state_version from public.weddings),null,'Manual synthetic task',null,null,null)$$,'manual shared task can be added');
select is((select count(*) from public.tasks where template_key is null),1::bigint,'manual identity distinct from templates');
select lives_ok($$select public.dismiss_draft_task((select id from wp12 where label='a'),(select id from public.tasks where template_key='shared.roles.v1'),(select state_version from public.weddings))$$,'draft dismissal persists');
select ok((select dismissed_at is not null and title='Edited synthetic task' from public.tasks where template_key='shared.roles.v1'),'dismissal retains edited title and template identity');
select throws_ok($$select public.dismiss_draft_task((select id from wp12 where label='a'),(select id from public.tasks where template_key='shared.invite-wording.v1'),(select state_version from public.weddings))$$,'23514',null,'retained dependent blocks prerequisite dismissal');
select throws_ok($$select public.save_draft_setup((select id from wp12 where label='a'),(select state_version from public.weddings),'A','Pune',null,true,null,'[{"title":"Haldi","guest_count":null}]')$$,'55000',null,'selection locked after generation');
select throws_ok($$select public.reopen_draft((select id from wp12 where label='a'),(select state_version from public.weddings),false,true)$$,'22023',null,'rebuild requires explicit confirmation');
select lives_ok($$select public.reopen_draft((select id from wp12 where label='a'),(select state_version from public.weddings),true,true)$$,'deliberate rebuild preserves manual tasks');
select lives_ok($$select public.save_draft_setup((select id from wp12 where label='a'),(select state_version from public.weddings),'A updated','Pune','2027-02-14',false,'0',(select jsonb_agg(jsonb_build_object('id',id,'title',title,'ceremony_date',ceremony_date,'guest_count',guest_count)) from public.ceremonies where not is_archived)||'[{"title":"Haldi","ceremony_date":null,"guest_count":null},{"title":"Mehendi","ceremony_date":null,"guest_count":null}]')$$,'second valid combination and known-zero ceiling supported');
select is((select budget_ceiling_paise from public.weddings),'0','known zero is not unknown');
select is(public.generate_draft((select id from wp12 where label='a'),(select state_version from public.weddings)),6,'rebuild inserts only tasks for added ceremonies');
select is((select count(*) from public.tasks where template_key is not null),18::bigint,'four-ceremony combination differs deterministically');
select is((select count(*) from public.tasks where template_key='shared.roles.v1' and dismissed_at is not null),1::bigint,'regeneration never revives dismissal');
select is((select count(*) from public.tasks where template_key is null and dismissed_at is null),1::bigint,'manual task survives rebuild');
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into wp12 values('b',public.create_wedding('WP12 synthetic B','Test city'),null);
select lives_ok($$select public.save_draft_setup((select id from wp12 where label='b'),(select state_version from public.weddings),'B draft','Test city',null,true,null,'[{"title":"Family gathering","ceremony_date":null,"guest_count":null}]')$$,'custom ceremony without forced ritual supported');
select public.generate_draft((select id from wp12 where label='b'),(select state_version from public.weddings));
insert into wp12(label,id) select 'bc',id from public.ceremonies limit 1;
insert into wp12(label,id) select 'bt',id from public.tasks limit 1;
select throws_ok($$select public.generate_draft((select id from wp12 where label='a'),'0')$$,'42501',null,'B cannot generate A draft');
select throws_ok($$select public.activate_plan((select id from wp12 where label='a'),'0',true)$$,'42501',null,'B cannot activate A');
select throws_ok($$select public.dismiss_draft_task((select id from wp12 where label='a'),gen_random_uuid(),'0')$$,'42501',null,'B cannot dismiss A tasks');
select set_config('request.jwt.claims','{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.edit_draft_task((select id from wp12 where label='a'),(select id from wp12 where label='bt'),(select state_version from public.weddings),'Forged',null,null,null)$$,'42501',null,'existing B task reference denied under A parent');
select throws_ok($$select public.add_draft_task((select id from wp12 where label='a'),(select state_version from public.weddings),(select id from wp12 where label='bc'),'Forged',null,null,null)$$,'23503',null,'existing B ceremony reference denied under A parent');
select throws_ok($$select public.add_draft_task((select id from wp12 where label='a'),'0',null,'Stale',null,null,null)$$,'40001',null,'stale write rejected before mutation');
select throws_ok($$select public.activate_plan((select id from wp12 where label='a'),(select state_version from public.weddings),false)$$,'22023',null,'activation confirmation required');
update wp12 set version=(select state_version from public.weddings) where label='a';
select lives_ok($$select public.activate_plan((select id from wp12 where label='a'),(select version from wp12 where label='a'),true)$$,'owned reviewed draft activates');
select is((select state from public.weddings),'ACTIVE','correct forward lifecycle transition');
select lives_ok($$select public.activate_plan((select id from wp12 where label='a'),(select version from wp12 where label='a'),true)$$,'repeat activation with original version idempotent');
select is((select count(*) from public.audit_events where action='PLAN_ACTIVATED'),1::bigint,'one activation audit only');
select is((select count(*) from public.tasks),19::bigint,'activation does not duplicate or discard tasks');
select throws_ok($$select public.reopen_draft((select id from wp12 where label='a'),(select state_version from public.weddings),true,true)$$,'55000',null,'ACTIVE cannot reopen as draft');
select throws_ok($$select public.save_draft_setup((select id from wp12 where label='a'),(select state_version from public.weddings),'Bad','Pune','2028-01-01',false,null,'[]')$$,'55000',null,'setup RPC cannot move active dates or counts');
select throws_ok($$update public.ceremonies set guest_count=999$$,'42501',null,'direct ACTIVE guest-count bypass remains denied');
reset role;
select throws_ok($$update wedding_private.weddings set wedding_date='2028-01-01' where id=(select id from wp12 where label='a')$$,'23514',null,'DB guard rejects active date mutation');
select ok(not has_column_privilege('authenticated','wedding_private.weddings','draft_locked','UPDATE'),'no direct client generation-state grant');
select ok(not has_function_privilege('anon','public.activate_plan(uuid,text,boolean)','EXECUTE'),'anonymous activation denied');
select * from finish();
rollback;
